                all_parameters.append(parameters.vararg.arg)
            if parameters.kwarg is not None:
                extra = {
                    key: value
                    for key, value in bindings.items()
                    if key not in all_parameters
                }
                for key in extra:
                    del bindings[key]
                mapping = Value(
                    key=_key(
                        "keywords",
                        symbol.file.relative_path,
                        str(node.lineno),
                        *self.call_sites,
                    )
                )
                self.mapping_keys.add(mapping.key)
                for key, value in extra.items():
                    env[self.member_key(mapping, key)] = value
                bindings[parameters.kwarg.arg] = mapping
                all_parameters.append(parameters.kwarg.arg)
            for parameter in all_parameters:
                if parameter not in bindings and parameter in defaults:
                    bindings[parameter] = self.expression(
                        helper, defaults[parameter], {}
                    )
            if (
                valid
                and set(bindings) == set(all_parameters)
                and not (
                    {parameter.arg for parameter in parameters.posonlyargs}
                    & keywords.keys()
                )
                and None not in keywords
            ):
                for name, value in self.closures.get(callable_value.key, {}).items():
                    bindings.setdefault(name, value)
                if bound_parameter is not None:
                    bindings[bound_parameter] = self.bound_receivers.get(
                        callable_value.key, receiver
                    )
                bindings.update(
                    (key, value)
                    for key, value in env.items()
                    if key.startswith(self.helper_state_prefixes)
                    and not key.startswith("#member:")
                )
                # Carry reachable object state, not every temporary object from
                # the caller. Globals, closures and bound methods remain roots.
                pending = (
                    [(value, False) for value in self.globals.values()]
                    + [(value, True) for value in bindings.values()]
                    + [
                        (self.module_values[file.relative_path], False)
                        for file in self.source_modules.values()
                    ]
                )
                reached: set[str] = set()
                while pending:
                    check_deadline(self.deadline)
                    current, from_argument = pending.pop()
                    if current.key in reached:
                        continue
                    reached.add(current.key)
                    # Scalars cannot expose additional helper state. Most cached
                    # globals and member values are leaves; do not build empty
                    # traversal generators and unknown-member tuples for them.
                    if (
                        current.key not in self.members
                        and current.key not in self.instance_alternatives
                        and current.key not in self.argument_tuples
                        and current.key not in self.closures
                        and current.key not in self.bound_receivers
                        and "#member:unknown:" + current.key not in env
                    ):
                        continue
                    pending.extend(
                        (original, from_argument)
                        for original in self.instance_alternatives.get(current.key, ())
                    )
                    pending.extend(
                        (value, from_argument)
                        for value in self.argument_tuples.get(current.key, ())
                    )
                    pending.extend(
                        (value, from_argument)
                        for value in self.closures.get(current.key, {}).values()
                    )
                    if current.key in self.bound_receivers:
                        pending.append(
                            (self.bound_receivers[current.key], from_argument)
                        )
                    for marker in (
                        *self.members.get(current.key, {}).values(),
                        "#member:unknown:" + current.key,
                    ):
                        if marker in env:
                            value = env[marker]
                            # Unchanged globals load on use; carry caller mutations.
                            if from_argument or value is not self.global_members.get(
                                marker
                            ):
                                bindings[marker] = value
                            pending.append((value, from_argument))
                        elif marker in self.global_members:
                            # An unused global's unchanged parent still leads to
                            # descendants mutated by an earlier caller.
                            pending.append((self.global_members[marker], False))
                initial_instances = {
                    value.key
                    for value in bindings.values()
                    if value.instance is not None
                }
                self.call_sites.append(
                    f"{symbol.file.relative_path}:{node.lineno}:{node.col_offset}"
                )
                try:
                    bindings["#callable-origin"] = callable_value
                    returned = self.function(helper, bindings)
                finally:
                    self.call_sites.pop()
                env.update(
                    (key, value)
                    for key, value in bindings.items()
                    if key.startswith(self.helper_state_prefixes)
                )
                invalidated = {
                    value.key
                    for value in bindings.values()
                    if value.key in initial_instances and value.instance is None
                }
                for key, value in env.items():
                    if value.key in invalidated:
                        env[key] = replace(value, instance=None)
                if constructing is not None and bound_parameter is not None:
                    initialized = bindings[bound_parameter]
                    if initialized.instance is None:
                        self.unresolved(
                            symbol,
                            node,
                            "custom construction replaced methods "
                            "or exposed instance state",
                        )
                    else:
                        for marker in self.members.get(initialized.key, {}).values():
                            if marker in env and not env[marker].maybe_missing:
                                self.member_defaults[marker] = Value(
                                    key="#missing", maybe_missing=True
                                )
                                self.required_members.add(marker)
                    return self.aggregate(initialized, env)
                # Propagate facts about actual values, not internal control markers.
                # Markers can share an empty key with unrelated unknown values.
                bound_values = [
                    value
                    for name, value in bindings.items()
                    if value.key
                    and not value.maybe_missing
                    and not value.maybe_none
                    and (
                        not name.startswith("#")
                        or name.startswith(("#member:", "#global-value:"))
                    )
                ]
                protected = {value.key for value in bound_values if value.contained}
                option_checked = {
                    value.key for value in bound_values if value.option_safe
                }
                url_checked: dict[str, Value] = {}
                for value in bound_values:
                    if value.url_checks:
                        previous = url_checked.get(value.key)
                        url_checked[value.key] = (
                            replace(
                                value,
                                url_checks=value.url_checks | previous.url_checks,
                                locations=value.locations | previous.locations,
                            )
                            if previous is not None
                            else value
                        )
                if protected or option_checked or url_checked:
                    for key, current in env.items():
                        checked = url_checked.get(current.key)
                        if (
                            checked
                            or current.key in protected
                            or current.key in option_checked
                        ):
                            env[key] = replace(
                                current,
                                contained=current.contained or current.key in protected,
                                option_safe=current.option_safe
                                or current.key in option_checked,
                                url_checks=current.url_checks | checked.url_checks
                                if checked
                                else current.url_checks,
                                locations=current.locations | checked.locations
                                if checked
                                else current.locations,
                            )
                return replace(
                    returned, locations=returned.locations | result.locations
                )
        self.http_context.unknown_call(node, (*values, receiver), env)
        self.workbooks.difference_update(value.key for value in (*values, receiver))
        escaped = {
            value.key
            for value in (*values, receiver)
            if value.instance is not None
            or value.key in self.mapping_keys
            or value.key in self.record_keys
        }
        escaped.update(
            original.key
            for key in tuple(escaped)
            for original in self.instance_alternatives.get(key, ())
        )
        escaped.update(
            alias_owner.key
            for key in tuple(escaped)
            if (
                alias_owner := self.optional_mappings.get(key)
                or self.http_context.state_owners.get(key)
            )
            is not None
        )
        if escaped:
            changed = replace(
                combine(values),
                contained=False,
                checked_path_parent=False,
                option_safe=False,
                url_checks=frozenset(),
                credential_present=False,
                instance=None,
                operator_opt_in=frozenset(),
            )
            for owner in escaped:
                for marker in self.members.get(owner, {}).values():
                    if marker in env:
                        env[marker] = replace(
                            combine([env[marker], changed]),
                            contained=False,
                            checked_path_parent=False,
                            option_safe=False,
                            url_checks=frozenset(),
                            credential_present=False,
                            instance=None,
                            operator_opt_in=frozenset(),
                            maybe_missing=True,
                        )
                env["#member:unknown:" + owner] = changed
            for key, value in env.items():
                if value.key in escaped:
                    env[key] = replace(value, instance=None)
        if result.sources:
            self.unresolved(symbol, node, f"unresolved call to {name}")
        return replace(
            result,
            key=_key(
                symbol.file.relative_path,
                str(node.lineno),
                str(node.col_offset),
                name,
                result.key,
            ),
            contained=False,
            checked_path_parent=False,
            path_object=False,
            repository_object=False,
            instance=None,
            option_safe=False,
            url_checks=frozenset(),
            credential_present=False,
            operator_opt_in=frozenset(),
        )

def _credential_guard_facts(
    absent_values: tuple[Value, ...], settings: tuple[tuple[str, Value], ...]
) -> Value:
    # Reuse only identical immutable guard values, never a mutable branch/env.
    absent = [
        value
        for value in absent_values
        if value.contained
        and any(source.startswith("http:") for source in value.sources)
    ]
    selected = {name: value for name, value in settings if value.contained}
    return Value(
        sources=frozenset().union(*(value.sources for value in absent)),
        locations=frozenset().union(
            *(value.locations for value in (*absent, *selected.values()))
        ),
        credential_fallback=bool(absent),
        operator_opt_in=frozenset(selected),
    )

def __init__(
        self, program: PythonProgram, state: RuleRunState, deadline: float
    ) -> None:
        super().__init__(program, state, deadline)
        self.evaluated: dict[ast.AST, Value] = {}
        self.environment_text: dict[str, tuple[str, str]] = {}
        self.operator_predicates: dict[str, tuple[str, bool]] = {}
        self.basic_auth_fields: dict[str, tuple[str, ...]] = {}
        # Index names only; guard values always come from the current branch.
        self.absent_markers: set[str] = set()
        self.opt_in_markers: set[str] = set()
        self.credential_guard_cache: (
            tuple[tuple[Value, ...], tuple[tuple[str, Value], ...], Value] | None
        ) = None

def conditioned_credential(self, value: Value, env: dict[str, Value]) -> Value:
        if not value.operator_credential:
            return value
        absent_values = tuple(env[name] for name in self.absent_markers & env.keys())
        settings = tuple(
            (name.removeprefix("#credential:opt-in:"), env[name])
            for name in self.opt_in_markers & env.keys()
        )
        cached = self.credential_guard_cache
        if cached is None or cached[0] != absent_values or cached[1] != settings:
            facts = _credential_guard_facts(absent_values, settings)
            self.credential_guard_cache = (absent_values, settings, facts)
        else:
            facts = cached[2]
        if not facts.credential_fallback and not facts.operator_opt_in:
            return value
        return replace(
            value,
            sources=value.sources | facts.sources
            if facts.credential_fallback
            else value.sources,
            locations=value.locations | facts.locations,
            credential_fallback=value.credential_fallback or facts.credential_fallback,
            operator_opt_in=value.operator_opt_in | facts.operator_opt_in
            if facts.operator_opt_in
            else value.operator_opt_in,
        )

def assign(self, target: ast.AST, value: Value, env: dict[str, Value]) -> None:
        if isinstance(target, ast.Name):
            original = env.get(target.id, UNKNOWN_VALUE)
            if (
                value.operator_credential
                and env.get("#absent:" + original.key, UNKNOWN_VALUE).contained
            ):
                value = replace(combine([value, original]), credential_fallback=True)
        super().assign(target, value, env)

def merge(self, env: dict[str, Value], branches: list[dict[str, Value]]) -> None:
        empty = UNKNOWN_VALUE
        http = [
            branch
            for branch in branches
            if branch.get("#credential:http", empty).contained
        ]
        # ponytail: follow the successful HTTP getter path; exception-prefix
        # correlation needs separate state. Keep the stdio alternative distinct.
        branches = http or branches
        super().merge(env, branches)
        if http:
            env["#credential:http"] = Value(contained=True)
        for name in (self.absent_markers | self.opt_in_markers) & env.keys():
            first = branches[0].get(name, empty) if branches else empty
            if all(branch.get(name, empty) is first for branch in branches[1:]):
                env[name] = first
                continue
            env[name] = (
                replace(combine([branch[name] for branch in branches]), contained=True)
                if all(branch.get(name, empty).contained for branch in branches)
                else empty
            )

def guard(
        self, symbol: Symbol, node: ast.AST, env: dict[str, Value], truth: bool
    ) -> None:
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            self.guard(symbol, node.operand, env, not truth)
            return
        if isinstance(node, ast.BoolOp):
            conjunctive = isinstance(node.op, ast.And)
            for child in node.values:
                if truth == conjunctive or all(
                    other is child
                    or self.truth_value(self.evaluated.get(other, UNKNOWN_VALUE), env)
                    is conjunctive
                    for other in node.values
                ):
                    self.guard(symbol, child, env, truth)
        if (
            isinstance(node, ast.Compare)
            and len(node.ops) == 1
            and isinstance(node.comparators[0], ast.Constant)
            and node.comparators[0].value is None
        ):
            if isinstance(node.ops[0], (ast.Is, ast.Eq)):
                self.guard(symbol, node.left, env, not truth)
            elif isinstance(node.ops[0], (ast.IsNot, ast.NotEq)):
                self.guard(symbol, node.left, env, truth)
            return
        value = self.evaluated.get(node, UNKNOWN_VALUE)
        http_input = any(source.startswith("http:") for source in value.sources)
        predicate = self.operator_predicates.get(value.key)
        if predicate is not None and truth != predicate[1]:
            marker = "#credential:opt-in:" + predicate[0]
            self.opt_in_markers.add(marker)
            env[marker] = Value(
                contained=True,
                locations=value.locations
                | {(symbol.file.relative_path, getattr(node, "lineno", 1))},
            )
        if not isinstance(node, (ast.Name, ast.Attribute, ast.Subscript)):
            if not truth and http_input:
                marker = "#credential:excluded:" + value.key
                self.absent_markers.add(marker)
                env[marker] = replace(
                    value,
                    contained=True,
                    locations=value.locations
                    | {(symbol.file.relative_path, getattr(node, "lineno", 1))},
                )
            return
        if http_input:
            if not truth:
                marker = "#absent:" + value.key
                self.absent_markers.add(marker)
                env[marker] = replace(
                    value,
                    contained=True,
                    locations=value.locations
                    | {(symbol.file.relative_path, getattr(node, "lineno", 1))},
                )
            for name, current in env.items():
                if current.key == value.key:
                    env[name] = replace(
                        current,
                        credential_present=truth,
                        locations=current.locations
                        | {(symbol.file.relative_path, getattr(node, "lineno", 1))},
                    )

def call(self, symbol: Symbol, node: ast.Call, env: dict[str, Value]) -> Value:
        external = self.external(symbol, node.func, env)
        if (
            external
            in {"httpx.BasicAuth", "requests.auth.HTTPBasicAuth", "aiohttp.BasicAuth"}
            and self.program.external(symbol, node.func) == external
        ):
            fields: tuple[str, ...] = (
                ("login", "password")
                if external == "aiohttp.BasicAuth"
                else ("username", "password")
            )
            arguments = [self.expression(symbol, arg, env) for arg in node.args]
            keywords = {
                keyword.arg: self.expression(symbol, keyword.value, env)
                for keyword in node.keywords
            }
            value = combine(
                [*arguments, *keywords.values()],
                _key(
                    external,
                    symbol.file.relative_path,
                    str(node.lineno),
                    str(node.col_offset),
                    *self.call_sites,
                ),
            )
            required = fields[:1] if external == "aiohttp.BasicAuth" else fields
            if (
                len(arguments) <= 2
                and not any(isinstance(arg, ast.Starred) for arg in node.args)
                and all(
                    name in fields
                    or (name == "encoding" and external == "aiohttp.BasicAuth")
                    for name in keywords
                )
                and not any(field in keywords for field in fields[: len(arguments)])
                and all(
                    index < len(arguments) or field in keywords
                    for index, field in enumerate(required)
                )
            ):
                self.record_keys.add(value.key)
                for index, field in enumerate(fields):
                    env[self.member_key(value, field)] = (
                        arguments[index]
                        if index < len(arguments)
                        else keywords.get(field, UNKNOWN_VALUE)
                    )
                if external == "httpx.BasicAuth":
                    fields = ("_auth_header",)
                    env[self.member_key(value, fields[0])] = value
                self.basic_auth_fields[value.key] = fields
                return replace(value, maybe_none=False, maybe_missing=False)
            return value
        service_client = external in {"atlassian.Jira", "atlassian.Confluence"} and (
            self.program.external(symbol, node.func) == external
        )
        if external in {"os.getenv", "os.environ.get"} and (
            self.program.external(symbol, node.func) == external
        ):
            args = [self.expression(symbol, arg, env) for arg in node.args]
            result = Value(
                key=_key(
                    symbol.file.relative_path,
                    str(node.lineno),
                    ast.dump(node),
                    *self.call_sites,
                    *(arg.key for arg in args),
                ),
                operator_credential=True,
                locations=frozenset({(symbol.file.relative_path, node.lineno)}),
            )
            if len(args) == 2 and not node.keywords:
                name, default = (member_label(arg) for arg in args)
                if isinstance(name, str) and isinstance(default, str):
                    self.environment_text[result.key] = (name, default)
            return result
        method = node.func.attr if isinstance(node.func, ast.Attribute) else ""
        receiver = self.call_receiver(symbol, node, env)
        client_request = self.http_client(receiver, method, env) and method in {
            "get",
            "post",
            "put",
            "patch",
            "delete",
            "head",
            "options",
            "request",
        }
        if (
            service_client
            or client_request
            or external
            in {
                f"{library}.{method}"
                for library in ("requests", "httpx")
                for method in (
                    "get",
                    "post",
                    "put",
                    "patch",
                    "delete",
                    "head",
                    "options",
                    "request",
                )
            }
        ):
            # Shared construction retains the client/session identity and evaluates
            # arguments once. Reuse those values for the credential sink check.
            constructed = super().call(symbol, node, env) if service_client else None
            arguments = [
                self.evaluated.get(argument, UNKNOWN_VALUE)
                if service_client
                else self.expression(symbol, argument, env)
                for argument in node.args
            ]
            keywords = {
                keyword.arg: (
                    self.evaluated.get(keyword.value, UNKNOWN_VALUE)
                    if service_client
                    else self.expression(symbol, keyword.value, env)
                )
                for keyword in node.keywords
            }
            credentials: list[Value] = []
            if service_client:
                credentials.extend(
                    keywords[field]
                    for field in ("token", "password")
                    if field in keywords
                )
            else:
                library = (
                    self.http_clients.get(receiver.key) if client_request else None
                )
                auth = keywords.get("auth")
                if library and (
                    auth is None
                    or (
                        auth.key == "None"
                        and library in {"requests.Session", "aiohttp.ClientSession"}
                    )
                ):
                    auth = self.member(
                        receiver,
                        "_default_auth"
                        if library == "aiohttp.ClientSession"
                        else "auth",
                        env,
                    )
                    if library == "aiohttp.ClientSession":
                        base = member_label(self.member(receiver, "_base_url", env))
                        index = 1 if method == "request" else 0
                        url = member_label(
                            keywords.get(
                                "url",
                                arguments[index]
                                if len(arguments) > index
                                else UNKNOWN_VALUE,
                            )
                        )
                        if (base is None or isinstance(base, str)) and isinstance(
                            url, str
                        ):
                            try:
                                origin, destination = (
                                    urlsplit(base or ""),
                                    urlsplit(urljoin(base or "", url)),
                                )
                                if destination.username is not None or (
                                    base is not None
                                    and (
                                        origin.scheme,
                                        origin.hostname,
                                        origin.port
                                        or (443 if origin.scheme == "https" else 80),
                                    )
                                    != (
                                        destination.scheme,
                                        destination.hostname,
                                        destination.port
                                        or (
                                            443 if destination.scheme == "https" else 80
                                        ),
                                    )
                                ):
                                    auth = Value(key="None")
                            except ValueError:
                                self.unresolved(
                                    symbol, node, "invalid aiohttp request URL"
                                )
                                return UNKNOWN_VALUE
                if auth is not None:
                    if auth.key in self.basic_auth_fields:
                        credentials.append(
                            combine(
                                [
                                    self.member(auth, name, env)
                                    for name in self.basic_auth_fields[auth.key]
                                ]
                            )
                        )
                    else:
                        credentials.append(auth)
                for field in ("headers", "params", "data", "json"):
                    values: dict[str, Value] = {}
                    mappings = []
                    if library and field in {"headers", "params"}:
                        mappings.append(self.member(receiver, field, env))
                    if field in keywords:
                        mappings.append(keywords[field])
                    for mapping in mappings:
                        values.update(
                            (name.lower() if field == "headers" else name, env[marker])
                            for name, marker in self.members.get(
                                mapping.key, {}
                            ).items()
                            if isinstance(name, str) and marker in env
                        )
                    if (
                        field == "headers"
                        and library == "aiohttp.ClientSession"
                        and auth is not None
                        and auth.key != "None"
                        and not auth.maybe_none
                        and not auth.maybe_missing
                        and auth.key in self.basic_auth_fields
                        and "authorization" in values
                    ):
                        self.unresolved(
                            symbol,
                            node,
                            "aiohttp rejects combined auth and Authorization header",
                        )
                        return UNKNOWN_VALUE
                    if (
                        field == "headers"
                        and auth is not None
                        and not auth.maybe_none
                        and not auth.maybe_missing
                        and (
                            (
                                auth.key in self.basic_auth_fields
                                and "#member:unknown:" + auth.key not in env
                            )
                            or (
                                self.sequence_keys.get(auth.key) is False
                                and len(self.sequence_elements(auth, env) or ()) == 2
                                and library != "aiohttp.ClientSession"
                            )
                        )
                    ):
                        values.pop("authorization", None)
                    credentials.extend(
                        value
                        for name, value in values.items()
                        if name.lower()
                        in {"authorization", "x-api-key", "access_token", "api_key"}
                    )
            conditioned = [
                self.conditioned_credential(value, env) for value in credentials
            ]
            crossing = combine(
                [value for value in conditioned if value.credential_fallback]
            )
            if crossing.credential_fallback and any(
                source.startswith("http:") for source in crossing.sources
            ):
                settings = {
                    key.removeprefix("#credential:opt-in:"): value
                    for key, value in env.items()
                    if key.startswith("#credential:opt-in:") and value.contained
                }
                setting_names = settings.keys() | crossing.operator_opt_in
                locations = crossing.locations | frozenset().union(
                    *(value.locations for value in settings.values())
                )
                self.state.matches.append(
                    replace(
                        match_from_node(
                            self.rule_id, symbol.file, node, "credential-fallback"
                        ),
                        captures={
                            "sink_name": qualified_name(node.func) or "request",
                            **(
                                {
                                    "credential_operator_opt_in": json.dumps(
                                        sorted(setting_names)
                                    )
                                }
                                if setting_names
                                else {}
                            ),
                            "flow_locations": json.dumps(
                                sorted(
                                    locations
                                    | {(symbol.file.relative_path, node.lineno)}
                                )
                            ),
                        },
                    )
                )
            return constructed if constructed is not None else UNKNOWN_VALUE
        result = super().call(symbol, node, env)
        if (
            method == "get"
            and receiver.key in self.context_variables
            and result.key == "None"
            and env.get("#credential:http", UNKNOWN_VALUE).contained
            and env.get("#http:no-request", UNKNOWN_VALUE).key != "True"
        ):
            result = replace(
                result,
                key=_key("absent-http-context", receiver.key),
                sources=frozenset({"http:request-context"}),
                locations=result.locations | {(symbol.file.relative_path, node.lineno)},
                maybe_none=True,
            )
            self.path_conditions[result.key] = (frozenset(), None)
        if (
            isinstance(node.func, ast.Attribute)
            and node.func.attr == "lower"
            and not node.args
            and not node.keywords
        ):
            original = self.evaluated.get(node.func.value, UNKNOWN_VALUE)
            selected = self.environment_text.get(original.key)
            if selected:
                result = replace(
                    original,
                    key=_key(original.key, "lower"),
                    locations=original.locations
                    | {(symbol.file.relative_path, node.lineno)},
                )
                self.environment_text[result.key] = (selected[0], selected[1].lower())
        if (
            external == "fastmcp.server.dependencies.get_http_request"
            and self.program.external(symbol, node.func) == external
            and not node.args
            and not node.keywords
        ):
            env["#credential:http"] = Value(contained=True)
        return result
